function typeInfo(c){c=String(c||'').toUpperCase();if(TYPES[c]){const[manufacturer,model,power,wake]=TYPES[c];return{code:c,manufacturer,model,power,wake}}if(/^A3/.test(c))return{code:c,manufacturer:'AIRBUS'};if(/^B7/.test(c))return{code:c,manufacturer:'BOEING'};if(/^C\d{3}$/.test(c))return{code:c,manufacturer:'CESSNA'};return{code:c||null}}function operatorName(a,f){const r=f?.airline_name;if(r&&r.length>3)return r;const c=f?.airline_icao||String(f?.flight_icao||a.call||'').slice(0,3).toUpperCase();return OPS[c]||r||f?.airline_iata||c||''}function hexState(h){const n=parseInt(String(h||''),16);if(n>=0xC00000&&n<=0xC3FFFF)return'CANADA';if(n>=0xA00000&&n<=0xAFFFFF)return'UNITED STATES';if(n>=0x400000&&n<=0x43FFFF)return'UNITED KINGDOM';if(n>=0x380000&&n<=0x3BFFFF)return'FRANCE';if(n>=0x3C0000&&n<=0x3FFFFF)return'GERMANY';return null}function phase(f){const status=String(f?.status||'').toUpperCase();return f?.current_assignment_established===true?(status||'OPERATION STATE UNKNOWN'):'ROUTE ASSOCIATION · OPERATION UNVERIFIED'}function motion(a){if(a.vr==null||a.vr===''||!Number.isFinite(Number(a.vr)))return'VERTICAL UNKNOWN';return a.vr>200?'CLIMBING':a.vr<-200?'DESCENDING':'LEVEL'}function delay(f){const raw=f?.arr_delayed??f?.dep_delayed??f?.delayed;if(raw==null||raw==='')return null;const n=Number(raw);return Number.isFinite(n)?(n<=4?'ON TIME':`${Math.round(n)} MIN LATE`):null}
